                ..
            } => {
                matches!(
                    unavailable_reason.as_str(),
                    "explicit_ultimate_payer_unavailable"
                        | "different_ultimate_payer_unnamed"
                        | "parent_cycle"
                        | "parent_payer_unavailable"
                        | "parent_evidence_unavailable"
                        | "parent_payer_ambiguous"
