                                    "donor" => payment.donor_funder_id.as_deref(),
                                    "payer" => payment.payer_funder_id.as_deref(),
                                    "ultimate_payer" => payment.ultimate_payer_funder_id.as_deref(),
                                    _ => None,
                                } != Some(row.funder_id.as_str())
